it('validates saved sizes and integer capped best scores as unknown input', () => {
  const storage = { getItem: () => JSON.stringify({ version: 1, size: 16,
    bests: { 4: 8, 6: -1, 8: 3.5, 10: 1000000, 12: '5', 14: 999999, 16: 128 } }), setItem: () => {} };
